# @spec docs/BACKLOG.md#sls-143 | docs/SCHEMA_011_REGRESSIONS.md#négatifs-des-finalisations-du-moniteur--sls-1435
# @verifies docs/BACKLOG.md#sls-143 | docs/SCHEMA_011_REGRESSIONS.md#négatifs-des-finalisations-du-moniteur--sls-1435
"""Six real owned-process faults, with terminal errors and independent cleanup."""
import json
import os
from pathlib import Path
import re
import runpy
import select
import signal
import stat
import subprocess
import sys
import threading
import time

ROOT = Path.cwd()
COMMON = runpy.run_path('e2e/editor-worker-preparation-failures.py')
BARRIER = runpy.run_path('.local/storage-observer-report-barrier.py')
InitialOutput, MonitorReadBarrier = (BARRIER[k] for k in ('InitialOutput', 'MonitorReadBarrier'))
identity, same_process, sha, atomic, diagnosis = (COMMON[k] for k in (
    'identity', 'same_process', 'sha', 'atomic', 'diagnosis'))
MODES = ('observer-primary-publication', 'controller-primary-publication',
         'controller-secondary-retain', 'controller-join-timeout',
         'observer-primary-finish', 'observer-secondary-print')


def owned(path, *, directory=False):
    info = path.lstat()
    assert info.st_uid == os.geteuid() and not path.is_symlink()
    assert stat.S_ISDIR(info.st_mode) if directory else stat.S_ISREG(info.st_mode)
    return {'device': info.st_dev, 'inode': info.st_ino, 'uid': info.st_uid,
            'mode': stat.S_IMODE(info.st_mode)}


def unchanged(path, expected, *, directory=False):
    current = owned(path, directory=directory)
    assert all(current[k] == expected[k] for k in ('device', 'inode', 'uid'))
    return current


def wait_value(read, deadline):
    while True:
        value = read()
        if value is not None:
            return value
        assert time.monotonic() < deadline, 'owned_diagnostic_observation_deadline'
        time.sleep(.001)


def read_json(path):
    try:
        return json.loads(path.read_bytes())
    except FileNotFoundError:
        return None


def metadata(path):
    raw = path.read_bytes()
    return {'path': str(path.relative_to(ROOT)), 'bytes': len(raw), 'sha256': sha(raw)}


def event_lines(path, event):
    values = []
    for line in path.read_bytes().splitlines():
        try:
            value = json.loads(line)
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
        if isinstance(value, dict) and value.get('event') == event:
            values.append(value)
    assert len(values) == 1, 'one_real_terminal_diagnostic_required'
    return values[0]


def run_case(mode, destination, worker, launch):
    assert mode in MODES and os.geteuid() != 0
    folder = destination / mode
    folder.mkdir(mode=0o700)
    is_controller = mode.startswith('controller-')
    pipe_output = mode in ('observer-primary-publication', 'controller-primary-publication',
                           'observer-secondary-print')
    program = Path('.local/run-storage-response-observer-finalization.py' if is_controller
                   else '.local/observe-storage-response-finalization.py')
    value = {'mode': mode, 'completed': False, 'groups_added': 0, 'failure': None,
             'cleanup_errors': [], 'started_at_ns': time.time_ns(),
             'program_sha256': sha(program.read_bytes())}
    primary = None
    child = None
    client_fd = monitor_fd = None
    stdout_file = stderr_file = stdout_reader = monitor_reader = None
    sink = monitor_sink = None
    barrier = None
    directories, collisions = [], []
    stream_restore = None
    monitor = None
    controller_work = monitor_work = None

    def failure(step, error):
        nonlocal primary
        value['cleanup_errors'].append({'step': step, **diagnosis(error)})
        if primary is None:
            primary = error
            value['failure'] = diagnosis(error)

    def add_directory(path):
        path.mkdir(mode=0o700)
        item = owned(path, directory=True)
        directories.append((path, item))
        return {'path': str(path.relative_to(ROOT)), **item}

    try:
        stderr_file = (folder / 'cli.stderr').open('xb')
        if not pipe_output:
            stdout_file = (folder / 'cli.stdout').open('xb')
        assert threading.active_count() == 1 and signal.getsignal(signal.SIGCHLD) == signal.SIG_DFL
        mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
        launch_error = None
        try:
            child = subprocess.Popen([sys.executable, '-B', str(program), worker.name],
                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE if pipe_output else stdout_file,
                stderr=stderr_file, cwd=ROOT, start_new_session=True,
                preexec_fn=lambda: signal.pthread_sigmask(signal.SIG_SETMASK, mask))
            client_fd = os.pidfd_open(child.pid)
            owner = identity(child.pid)
            assert owner['parent'] == os.getpid() and owner['uid'] == os.geteuid()
            same_process(owner)
        except BaseException as error:
            launch_error = error
        finally:
            try:
                signal.pthread_sigmask(signal.SIG_SETMASK, mask)
            except BaseException as error:
                if launch_error is None:
                    launch_error = error
                else:
                    value['cleanup_errors'].append({'step': 'launch-mask', **diagnosis(error)})
        if launch_error is not None:
            raise launch_error
        value['client_identity'] = owner
        if pipe_output:
            sink = InitialOutput(child.stdout.fileno(), pipe=True)
        else:
            stdout_reader = (folder / 'cli.stdout').open('rb')
            sink = InitialOutput(stdout_reader.fileno(), pipe=False)
        if is_controller:
            initial = wait_value(sink.first, time.monotonic() + 15)
            result_path = ROOT / initial['controller_result']
            controller_work = result_path.parent
            assert controller_work.parent == worker and result_path.name == 'result.json'
            assert re.fullmatch('storage-response-observer-controller-[0-9a-f]{32}', controller_work.name)
            assert owned(controller_work, directory=True)['mode'] == 0o700
            def monitor_record():
                record = read_json(result_path)
                return record if record is not None and 'observer_identity' in record else None
            record = wait_value(monitor_record, time.monotonic() + 15)
            assert record['controller_identity']['pid'] == child.pid
            assert record['controller_identity']['birth'] == owner['birth']
            monitor = identity(record['observer_identity']['pid'])
            assert monitor['birth'] == record['observer_identity']['birth']
            assert monitor['parent'] == child.pid and monitor['uid'] == os.geteuid()
            expected = [os.fsencode(x) for x in (
                sys.executable, '-B', '.local/observe-storage-response-finalization.py', worker.name)]
            assert Path('/proc', str(monitor['pid']), 'cmdline').read_bytes().rstrip(b'\0').split(b'\0') == expected
            monitor_fd = os.pidfd_open(monitor['pid'])
            same_process(monitor)
            output_path = controller_work / 'observer.stdout'
            output_identity = owned(output_path)
            assert output_identity['mode'] == 0o600
            monitor_reader = output_path.open('rb')
            info = os.fstat(monitor_reader.fileno())
            assert (info.st_dev, info.st_ino) == (output_identity['device'], output_identity['inode'])
            monitor_sink = InitialOutput(monitor_reader.fileno(), pipe=False)
            value['controller_work'] = str(controller_work.relative_to(ROOT))
        else:
            monitor, monitor_fd, monitor_sink = owner, client_fd, sink
        value['monitor_identity'] = monitor
        assert monitor['pid_namespace'] == owner['pid_namespace']
        barrier = MonitorReadBarrier(monitor, monitor_fd, monitor_sink, worker, launch)
        if mode in MODES[:4]:
            value['barrier'] = barrier.hold_report_read()
        else:
            value['barrier'] = barrier.hold_initial_output()
        monitor_work = barrier.work
        value['monitor_work'] = str(monitor_work.relative_to(ROOT))
        if mode == 'observer-primary-publication':
            value['pending_collision'] = add_directory(monitor_work / 'checkpoint.pending')
            child.stdout.close(); sink.closed = True
            value['signal_delivery'] = barrier.deliver(signal.SIGTERM)
        elif mode in ('controller-primary-publication', 'controller-secondary-retain'):
            output_path = controller_work / 'observer.stdout'
            stream_restore = (monitor_reader.fileno(), output_path, owned(output_path))
            os.fchmod(monitor_reader.fileno(), 0)
            assert unchanged(output_path, stream_restore[2])['mode'] == 0
            value['read_permission_denied'] = True
            if mode == 'controller-primary-publication':
                value['pending_collision'] = add_directory(controller_work / 'result.pending')
                child.stdout.close(); sink.closed = True
                same_process(owner)
                signal.pidfd_send_signal(client_fd, signal.SIGINT)
                value['signal_delivery'] = barrier.deliver(signal.SIGTERM, send=False)
            else:
                value['signal_delivery'] = barrier.deliver(signal.SIGTERM)
        elif mode == 'controller-join-timeout':
            value['signal_delivery'] = barrier.deliver(signal.SIGSTOP)
            same_process(owner)
            value['controller_interrupt_monotonic_ns'] = time.monotonic_ns()
            signal.pidfd_send_signal(client_fd, signal.SIGINT)
        elif mode == 'observer-primary-finish':
            barrier.release()
            def armed():
                record = read_json(monitor_work / 'checkpoint.json')
                return record if record is not None and record['phase'] == 'observing_first_response' and 'native_trace_start' in record else None
            record = wait_value(armed, time.monotonic() + 30)
            value['native_trace_armed'] = record['native_trace_start']
            value['finish_barrier'] = barrier.hold_report_read(phase='observing_first_response')
            collision = monitor_work / 'native-agent-trace-finish-transport.json'
            with collision.open('xb'):
                pass
            collisions.append((collision, owned(collision)))
            value['signal_delivery'] = barrier.deliver(signal.SIGTERM)
        else:
            child.stdout.close(); sink.closed = True
            barrier.release()
        value['fault_observed_at_ns'] = time.time_ns()
        atomic(folder / 'checkpoint.json', value)
        deadline = time.monotonic() + 300
        heartbeat = time.monotonic() + 10
        while child.poll() is None:
            assert time.monotonic() < deadline, 'diagnostic_client_deadline'
            if time.monotonic() >= heartbeat:
                print(json.dumps({'mode': mode, 'state': 'waiting', 'client_alive': True}), flush=True)
                heartbeat = time.monotonic() + 10
            time.sleep(.01)
        value.update(actual_client_exit_code=child.wait(), client_joined=True,
                     client_finished_monotonic_ns=time.monotonic_ns())
        assert value['actual_client_exit_code'] != 0, 'negative_client_became_success'
        value['monitor_joined_before_cleanup'] = bool(select.select([monitor_fd], [], [], 0)[0])
        assert value['monitor_joined_before_cleanup'], 'tested_program_did_not_join_monitor'
    except BaseException as error:
        primary = error
        value['failure'] = diagnosis(error)
    finally:
        if barrier is not None:
            try:
                barrier.release()
            except BaseException as error:
                failure('trace-detach', error)
            value['native_barrier_observation'] = barrier.observation()
        if child is not None and child.returncode is None:
            try:
                value['rescued_session_members'] = COMMON['kill_owned_session'](child)
            except BaseException as error:
                failure('client-join', error)
            if child.returncode is not None:
                value['actual_client_exit_code'] = child.returncode
        if monitor_fd is not None:
            try:
                if not select.select([monitor_fd], [], [], 0)[0]:
                    same_process(monitor)
                    signal.pidfd_send_signal(monitor_fd, signal.SIGCONT)
                    signal.pidfd_send_signal(monitor_fd, signal.SIGKILL)
                    assert select.select([monitor_fd], [], [], 5)[0]
                    value['monitor_rescue_used'] = True
            except BaseException as error:
                failure('monitor-join', error)
        if stream_restore is not None:
            try:
                fd, path, expected = stream_restore
                os.fchmod(fd, expected['mode'])
                assert unchanged(path, expected)['mode'] == expected['mode']
                value['read_permission_restored'] = True
            except BaseException as error:
                failure('permission', error)
        for path, expected in directories:
            try:
                unchanged(path, expected, directory=True)
                path.rmdir()
            except BaseException as error:
                failure('directory', error)
        for path, expected in collisions:
            try:
                unchanged(path, expected)
                assert path.read_bytes() == b''
                path.unlink()
            except BaseException as error:
                failure('collision', error)
        for label, stream in (('stdout-reader', stdout_reader), ('monitor-reader', monitor_reader),
                              ('stdout-file', stdout_file), ('stderr-file', stderr_file)):
            if stream is not None:
                try:
                    stream.close()
                except BaseException as error:
                    failure(label + '-close', error)
        if child is not None and child.stdout is not None and not child.stdout.closed:
            try:
                child.stdout.close()
            except BaseException as error:
                failure('stdout-pipe-close', error)
        for fd in set(x for x in (client_fd, monitor_fd) if x is not None):
            try:
                os.close(fd)
            except BaseException as error:
                failure('pidfd-close', error)
    value['transports'] = {}
    paths = {'cli-stderr': folder / 'cli.stderr'}
    if pipe_output and sink is not None:
        try:
            p = folder / 'cli.stdout-prefix'
            p.write_bytes(sink.prefix);p.chmod(0o600)
            paths['cli-stdout-prefix'] = p
            value['stdout_pipe_capture_is_partial'] = True
        except BaseException as error:
            failure('stdout-prefix-retain', error)
    elif stdout_file is not None:
        paths['cli-stdout'] = folder / 'cli.stdout'
    if controller_work is not None:
        paths.update({'monitor-stdout': controller_work / 'observer.stdout',
                      'monitor-stderr': controller_work / 'observer.stderr'})
    for label, path in paths.items():
        try:
            value['transports'][label] = metadata(path)
        except BaseException as error:
            failure(label + '-retain', error)
    try:
        if primary is not None:
            raise primary
        assert not value['cleanup_errors'] and not value.get('monitor_rescue_used')
        if mode == 'controller-join-timeout':
            terminal = json.loads((controller_work / 'result.json').read_bytes())
            assert terminal['failure']['type'] == 'KeyboardInterrupt'
            assert terminal['finalization_failures'] == [] and terminal['joined'] and terminal['returncode'] == -9
            assert value['client_finished_monotonic_ns'] - value['controller_interrupt_monotonic_ns'] >= 110 * 10**9
        else:
            terminal = event_lines(folder / 'cli.stderr', 'controller-finalization-failed' if is_controller else 'observer-finalization-failed')
            expected_primary = None if mode in ('controller-secondary-retain', 'observer-secondary-print') else 'KeyboardInterrupt' if is_controller else 'InterruptedError'
            assert (terminal['primary']['type'] if terminal['primary'] is not None else None) == expected_primary
            expected = {
                'observer-primary-publication': [('save', 'IsADirectoryError', 21), ('print', 'BrokenPipeError', 32)],
                'controller-primary-publication': [('retain_stdout', 'PermissionError', 13), ('save', 'IsADirectoryError', 21), ('print', 'BrokenPipeError', 32)],
                'controller-secondary-retain': [('retain_stdout', 'PermissionError', 13)],
                'observer-primary-finish': [('native_trace_finish', 'AssertionError', None)],
                'observer-secondary-print': [('print', 'BrokenPipeError', 32)],
            }[mode]
            assert [(x['step'], x['type'], x['errno']) for x in terminal['secondary']] == expected
            if is_controller:
                assert terminal['joined'] and terminal['returncode'] == 1
        value['terminal'] = terminal
        if mode == 'observer-secondary-print':
            intermediate = json.loads((monitor_work / 'checkpoint.json').read_bytes())
            assert intermediate['completed'] and intermediate.get('failure') is None and not intermediate['finalization_failures']
            value['intermediate_report'] = intermediate
        value['completed'] = True
    except BaseException as error:
        if primary is None:
            primary = error
            value['failure'] = diagnosis(error)
    value['finished_at_ns'] = time.time_ns()
    try:
        atomic(folder / 'checkpoint.json', value)
    except BaseException as error:
        failure('checkpoint-save', error)
    try:
        print(json.dumps({'mode': mode, 'completed': value['completed'] and primary is None,
                          'groups_added': 0, 'checkpoint': str((folder / 'checkpoint.json').relative_to(ROOT))}), flush=True)
    except BaseException as error:
        failure('result-print', error)
    if primary is not None:
        raise primary
    return value

