# @verifies docs/BACKLOG.md#sls-143 | docs/SCHEMA_011_REGRESSIONS.md#négatifs-des-finalisations-du-moniteur--sls-1435
"""Hold the owned monitor at its real protected report read; no memory access."""
import json
import os
from pathlib import Path
import re
import runpy
import select
import signal
import stat
import time

ROOT = Path.cwd()
COMMON = runpy.run_path('e2e/editor-worker-preparation-failures.py')
Trace = COMMON['PayloadWriter']
identity, same_process, sha = (COMMON[k] for k in ('identity', 'same_process', 'sha'))


class InitialOutput:
    """Retain only bytes really received from the one existing output reader."""
    def __init__(self, fd, *, pipe):
        self.fd, self.pipe, self.prefix, self.closed = fd, pipe, b'', False
        info = os.fstat(fd)
        assert info.st_uid == os.geteuid()
        assert stat.S_ISFIFO(info.st_mode) if pipe else stat.S_ISREG(info.st_mode)
        self.inode = (info.st_dev, info.st_ino)

    def first(self):
        assert not self.closed
        if self.pipe:
            if b'\n' not in self.prefix and select.select([self.fd], [], [], 0)[0]:
                part = os.read(self.fd, 65537 - len(self.prefix))
                assert part, 'initial_output_eof'
                self.prefix += part
        else:
            self.prefix = os.pread(self.fd, 65537, 0)
        assert len(self.prefix) <= 65536, 'initial_output_limit'
        if b'\n' not in self.prefix:
            return None
        return json.loads(self.prefix.split(b'\n', 1)[0])


class MonitorReadBarrier:
    def __init__(self, owner, pidfd, sink, worker, launch):
        self.owner, self.pidfd, self.sink = owner, pidfd, sink
        self.worker, self.launch = worker, launch
        self.trace = Trace(owner, pidfd)
        self.marker, self.work, self.read = None, None, None
        self.expected_phase = 'waiting_for_canonical_case'
        self.report = ROOT / launch['report_path']
        assert self.report.resolve() == self.report
        assert owner['uid'] == os.geteuid()

    def attach(self):
        current = same_process(self.owner)
        assert current['tracer_pid'] == 0 and current['state'] not in ('T', 't')
        self.trace.ptrace(0x4206, 0, 1)
        self.trace.attached = True
        self.trace.ptrace(0x4207)
        self.trace.wait(time.monotonic() + 5)

    def initial_output(self):
        if self.marker is not None:
            return True
        value = self.sink.first()
        if value is None:
            return False
        assert value['monitor_identity']['pid'] == self.owner['pid']
        assert value['monitor_identity']['birth'] == self.owner['birth']
        work = ROOT / value['work']
        assert work.parent == self.worker
        assert re.fullmatch('storage-response-observation-[0-9a-f]{32}', work.name)
        info = work.lstat()
        assert stat.S_ISDIR(info.st_mode) and info.st_uid == os.geteuid()
        assert not work.is_symlink() and stat.S_IMODE(info.st_mode) == 0o700
        self.marker, self.work = value, work
        return True

    def stdout_matches(self, descriptor):
        try:
            info = Path('/proc', str(self.owner['pid']), 'fd', str(descriptor)).stat()
        except FileNotFoundError:
            return False
        return (info.st_dev, info.st_ino) == self.sink.inode

    def opened_report(self, descriptor):
        path = Path('/proc', str(self.owner['pid']), 'fd', str(descriptor))
        try:
            target = os.readlink(path)
        except FileNotFoundError:
            return None
        if target not in (str(self.report), str(self.report) + ' (deleted)'):
            return None
        before = path.stat()
        assert stat.S_ISREG(before.st_mode) and before.st_uid == os.geteuid()
        fd = os.open(path, os.O_RDONLY)
        try:
            info = os.fstat(fd)
            assert (info.st_dev, info.st_ino) == (before.st_dev, before.st_ino)
            assert info.st_size <= 16 * 1024 ** 2, 'suite_report_read_limit'
            raw = os.pread(fd, 16 * 1024 ** 2 + 1, 0)
            assert len(raw) == info.st_size
        finally:
            os.close(fd)
        report = json.loads(raw)
        assert info.st_mtime_ns >= self.launch['created_at_ns']
        assert report['scope'] == self.launch['scope']
        assert report['source_commit'] == self.launch['source_commit']
        assert isinstance(report['run_id'], str) and re.fullmatch('[0-9a-f]{32}', report['run_id'])
        assert all(row['before']['source_sha256'] == self.launch['source_sha256']
                   for row in report['commands'] + report['prerequisites'])
        checkpoint = json.loads((self.work / 'checkpoint.json').read_bytes())
        assert checkpoint['run_id'] == report['run_id']
        assert checkpoint['phase'] == self.expected_phase
        if self.expected_phase == 'waiting_for_canonical_case':
            assert 'native_trace_start' not in checkpoint
        else:
            assert checkpoint['native_trace_start']['completed'] and 'native_trace_finish' not in checkpoint
        return {'syscall': 0, 'fd': descriptor, 'device': info.st_dev, 'inode': info.st_ino,
                'uid': info.st_uid, 'bytes': len(raw), 'sha256': sha(raw),
                'phase': self.expected_phase,
                'run_id': report['run_id'], 'observed_at_ns': time.time_ns(),
                'observed_monotonic_ns': time.monotonic_ns()}

    def hold_report_read(self, *, phase='waiting_for_canonical_case'):
        assert phase in ('waiting_for_canonical_case', 'observing_first_response')
        self.expected_phase = phase
        self.attach()
        deadline = time.monotonic() + 15
        while True:
            self.initial_output()
            if os.WSTOPSIG(self.trace.last_status) == (signal.SIGTRAP | 0x80):
                op, args = self.trace.info()
                if self.marker is not None and op == 1 and args[0] == 0:
                    observed = self.opened_report(args[1])
                    if observed is not None:
                        self.read = observed
                        return {'initial': self.marker, 'read': observed}
            self.trace.resume(self.trace.delivered_signal())
            self.trace.wait(deadline)

    def hold_initial_output(self):
        """Stop after the successful first print, before any forced pipe closure."""
        self.attach()
        deadline = time.monotonic() + 15
        pending = False
        while True:
            if self.initial_output():
                return {'initial': self.marker, 'initial_stdout_received': True,
                        'observed_monotonic_ns': time.monotonic_ns()}
            if os.WSTOPSIG(self.trace.last_status) == (signal.SIGTRAP | 0x80):
                op, args = self.trace.info()
                if op == 1:
                    pending = args[0] in (1, 20) and self.stdout_matches(args[1])
                elif op == 2 and pending and args > 0 and self.initial_output():
                    return {'initial': self.marker, 'stdout_write_returned_bytes': args,
                            'observed_monotonic_ns': time.monotonic_ns()}
            self.trace.resume(self.trace.delivered_signal())
            self.trace.wait(deadline)

    def deliver(self, signum, *, send=True):
        assert self.trace.attached and self.trace.stopped
        if send:
            signal.pidfd_send_signal(self.pidfd, signum)
        deadline = time.monotonic() + 5
        while True:
            self.trace.resume(self.trace.delivered_signal())
            got = self.trace.wait(deadline)
            if got == signum and self.trace.last_status >> 16 == 0:
                break
        delivered_at = time.monotonic_ns()
        self.trace.ptrace(17, 0, signum)
        self.trace.attached, self.trace.stopped = False, False
        result = {'signal': signum, 'delivery_wait_status': self.trace.last_status,
                  'delivered_monotonic_ns': delivered_at}
        if signum == signal.SIGSTOP:
            while True:
                current = same_process(self.owner)
                if current['state'] == 'T' and current['tracer_pid'] == 0:
                    break
                assert time.monotonic() < deadline, 'monitor_group_stop_not_confirmed'
                time.sleep(.001)
            result['stopped_identity'] = current
        return result

    def release(self):
        self.trace.release_trace()

    def observation(self):
        return {'identity': self.owner, 'initial_output': self.marker,
                'protected_read': self.read, 'trace': self.trace.observation()}

# @spec docs/BACKLOG.md#sls-143 | docs/CONSOLE_STORAGE.md#preuves-attendues
# @verifies docs/BACKLOG.md#sls-143 | docs/SCHEMA_011_REGRESSIONS.md
"""Observe one running canonical suite case; issue no business request or retry."""
